import java.util.Arrays;

public class Main {
  public static void main(String[] args) {
    int[] arr = {41, 42, 43, 44};

    // Usando Streams en Java (versión moderna)
    int[] nuevoarr = Arrays.stream(arr)
                           .filter(n -> n > 42)
                           .toArray();

    System.out.println(Arrays.toString(nuevoarr));
  }
}
